// Package differential implements the per-round scope passes from
// plans/porting.md §3: a registry-vs-catalog reconciliation for every
// ported family plus the twin-container scenario manifest that the
// nightly differential workflow (testing.md §differential) will consume
// once Salt runtime containers are available.
//
// The golden report under docs/differential/<round>/ is generated by this
// test; stale reports fail CI so the report cannot drift from code.
package differential

import (
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"

	"github.com/friz-zy/statekit/internal/bootstrap"
	"github.com/friz-zy/statekit/internal/runtime"

	"gopkg.in/yaml.v3"
)

// r2Families lists the execution families ported during round R2.
var r2Families = []string{"iptables", "ipset", "nftables", "bridge", "ps", "network"}

// scenarioManifest pins the twin-container scenarios the nightly
// differential run must execute once Salt runtime containers land
// (testing.md §Workflows, differential.yml). IDs follow the testing.md
// real-case naming convention.
var scenarioManifest = map[string][]string{
	"iptables": {
		"iptables.build-rule.restore-validate",
		"iptables.append-check-delete-cycle",
		"iptables.policy-set-get-roundtrip",
		"iptables.save-filtered-dump",
	},
	"ipset": {
		"ipset.create-add-test-del-destroy",
		"ipset.membership-range-matrix",
		"ipset.timeout-support-errors",
	},
	"nftables": {
		"nftables.build-rule.nft-c-validate",
		"nftables.table-chain-lifecycle",
		"nftables.flush-and-policy",
	},
	"bridge": {
		"bridge.add-addif-show-delif-delbr",
		"bridge.stp-toggle-vm-required",
	},
	"ps": {
		"ps.pgrep-pkill-vs-procps",
		"ps.top-cpu-sample-sanity",
		"ps.active-tcp-vs-proc-net",
	},
	"network": {
		"network.calc-net-in-subnet-vs-ipaddress",
		"network.reverse-ip-vs-reverse-pointer",
		"network.interfaces-routes-vs-iproute2",
		"network.ping-traceroute-dig-wrappers",
	},
}

type catalogFile struct {
	Functions []struct {
		Function string `yaml:"function"`
	} `yaml:"functions"`
}

type familyReport struct {
	Catalog       int      `yaml:"catalog_functions"`
	Public        int      `yaml:"public_functions"`
	Private       int      `yaml:"private_functions"`
	Registered    int      `yaml:"registered_public"`
	PendingPublic []string `yaml:"pending_public,omitempty"`
	Scenarios     []string `yaml:"differential_scenarios"`
}

type roundReport struct {
	Round    string                  `yaml:"round"`
	Families map[string]familyReport `yaml:"families"`
	Totals   struct {
		Catalog   int `yaml:"catalog_functions"`
		Public    int `yaml:"public_functions"`
		Registred int `yaml:"registered_public"`
	} `yaml:"totals"`
}

func loadCatalogFunctionNames(t *testing.T, family string) []string {
	t.Helper()
	path := filepath.Join("..", "..", "docs", "catalog", "exec", family+".yaml")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("catalog %s: %v", family, err)
	}
	var cf catalogFile
	if err := yaml.Unmarshal(data, &cf); err != nil {
		t.Fatalf("catalog %s parse: %v", family, err)
	}
	names := make([]string, 0, len(cf.Functions))
	for _, fn := range cf.Functions {
		names = append(names, fn.Function)
	}
	sort.Strings(names)
	return names
}

func TestR2DifferentialReport(t *testing.T) {
	rt, err := bootstrap.BuildRuntime()
	if err != nil {
		t.Fatal(err)
	}
	registered := registeredNames(rt)

	report := roundReport{Round: "R2", Families: map[string]familyReport{}}
	for _, family := range r2Families {
		catalogNames := loadCatalogFunctionNames(t, family)
		fam := familyReport{
			Catalog:   len(catalogNames),
			Scenarios: scenarioManifest[family],
		}
		for _, name := range catalogNames {
			if strings.HasPrefix(name, "_") {
				fam.Private++
				continue
			}
			fam.Public++
			full := family + "." + name
			if registered[full] {
				fam.Registered++
				continue
			}
			// Salt's keyword-escape convention: a trailing underscore in the
			// catalog name resolves through __func_alias__ to the stripped
			// CLI-facing name (list_ -> list).
			alias := strings.TrimSuffix(name, "_")
			if alias != name && registered[family+"."+alias] {
				fam.Registered++
				continue
			}
			fam.PendingPublic = append(fam.PendingPublic, full)
		}
		report.Totals.Catalog += fam.Catalog
		report.Totals.Public += fam.Public
		report.Totals.Registred += fam.Registered
		report.Families[family] = fam
	}

	encoded, err := yaml.Marshal(report)
	if err != nil {
		t.Fatal(err)
	}

	outPath := filepath.Join("..", "..", "docs", "differential", "R2", "report.yaml")
	want := "# Generated by tests/differential (TestR2DifferentialReport); do not edit.\n" + string(encoded)

	existing, rerr := os.ReadFile(outPath)
	if rerr == nil && string(existing) == want {
		return
	}
	if os.Getenv("UPDATE_DIFFERENTIAL") == "1" {
		if mkerr := os.MkdirAll(filepath.Dir(outPath), 0o755); mkerr != nil {
			t.Fatal(mkerr)
		}
		if werr := os.WriteFile(outPath, []byte(want), 0o644); werr != nil {
			t.Fatal(werr)
		}
		return
	}
	t.Fatalf("differential report stale; run UPDATE_DIFFERENTIAL=1 go test ./tests/differential\n--- want ---\n%s", want)
}

func registeredNames(rt *runtime.Runtime) map[string]bool {
	out := map[string]bool{}
	for _, name := range rt.Exec.Names() {
		out[name] = true
	}
	return out
}

// The reconciliation must never claim coverage for a family whose
// registered surface is empty — guards against registration dropouts.
func TestNoEmptyRegistrations(t *testing.T) {
	rt, err := bootstrap.BuildRuntime()
	if err != nil {
		t.Fatal(err)
	}
	if len(rt.Exec.Names()) == 0 {
		t.Fatal("exec registry empty after bootstrap")
	}
	if reflect.DeepEqual(rt.Exec.Names(), []string{}) {
		t.Fatal("unreachable")
	}
}
